static int[] pair(int[] sorted, int target) {
    int left = 0;
    int right = sorted.length - 1;
    while (left < right) {
        int sum = sorted[left] + sorted[right];
        if (sum == target) return new int[] {sorted[left], sorted[right]};
        if (sum < target) {
            left++;
        } else {
            right--;
        }
    }
    return new int[0];
}

