static void combine(int start, int r) {
    if (path.size() == r) {
        results.add(new ArrayList<>(path));
        return;
    }
    for (int i = start; i < items.length; i++) {
        path.add(items[i]);
        combine(start + 1, r);
        path.remove(path.size() - 1);
    }
}

