int n = 5;
int[][] edges = {{0, 2}, {1, 2}, {2, 3}, {1, 4}, {4, 3}};
List<List<Integer>> next = new ArrayList<>();
for (int i = 0; i < n; i++) next.add(new ArrayList<>());
int[] inDegree = new int[n];
for (int[] e : edges) {
    next.get(e[0]).add(e[1]);
    inDegree[e[1]]++;
}
Queue<Integer> queue = new ArrayDeque<>();
for (int i = 0; i < n; i++) {
    if (inDegree[i] == 0) queue.add(i);
}
List<Integer> order = new ArrayList<>();
while (!queue.isEmpty()) {
    int now = queue.poll();
    order.add(now);
    for (int after : next.get(now)) {
        inDegree[after]--;
        if (inDegree[after] == 0) queue.add(after);
    }
}
System.out.println(order);

static int[][] rotateRight(int[][] board) {
    int n = board.length;
    int m = board[0].length;
    int[][] result = new int[m][n];
    for (int r = 0; r < n; r++) {
        for (int c = 0; c < m; c++) {
            result[c][n - 1 - r] = board[r][c];
        }
    }
    return result;
}

