static int countRooms(List<Meeting> meetings) {
    List<Meeting> sorted = new ArrayList<>(meetings);
    sorted.sort(Comparator.comparingInt(Meeting::start));
    PriorityQueue<Integer> endTimes = new PriorityQueue<>();
    int rooms = 0;
    for (Meeting m : sorted) {
        if (!endTimes.isEmpty() && endTimes.peek() <= m.start()) {
            endTimes.poll();
        }
        endTimes.offer(m.end());
        rooms = Math.max(rooms, endTimes.size());
    }
    return rooms;
}

static int gcd(int a, int b) {
    while (b != 0) {
        a = b;
        b = a % b;
    }
    return a;
}

static boolean[] sieve(int n) {
    boolean[] composite = new boolean[n + 1];
    composite[0] = true;
    composite[1] = true;
    for (int i = 2; i * i <= n; i++) {
        if (composite[i]) continue;
        for (int j = i * i; j <= n; j += i) {
            composite[j] = true;
        }
    }
    return composite;
}

static boolean isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) return false;
    }
    return true;
}

static long[][] pascal(int n) {
    long[][] c = new long[n + 1][n + 1];
    for (int i = 0; i <= n; i++) {
        c[i][0] = 1;
        c[i][i] = 1;
        for (int j = 1; j < i; j++) {
            c[i][j] = c[i - 1][j - 1] + c[i - 1][j];
        }
    }
    return c;
}

static String toBinary(int n) {
    String digits = "";
    while (n > 0) {
        digits = (n % 2) + digits;
        n /= 2;
    }
    return digits;
}

