static long power(long a, long n, long m) {
    if (n == 0) return 1;
    long result = power(a, n / 2, m) * power(a, n / 2, m) % m;
    if (n % 2 == 1) result = result * a % m;
    return result;
}

static long power(long a, long n, long m) {
    long result = 1;
    a %= m;
    while (n > 0) {
        if ((n & 1) == 1) result = result * a % m;
        a = a * a % m;
        n >>= 1;
    }
    return result;
}
